package com.example.billing.service;
import static com.example.billing.api.Contracts.*; import com.example.billing.domain.*; import com.example.billing.persistence.Repositories.*; import java.time.*; import java.util.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CustomerService {private final CustomerRepository repo;private final Clock clock;public CustomerService(CustomerRepository r,Clock c){repo=r;clock=c;}public CustomerResponse create(CreateCustomerRequest r){var email=CatalogService.req(r.email());if(repo.existsByEmail(email))throw new IllegalStateException("Customer email '"+email+"' is already registered.");var x=new Customer();x.id=UUID.randomUUID();x.email=email;x.companyName=CatalogService.req(r.companyName());x.billingAddress=CatalogService.req(r.billingAddress());x.paymentMethodId=CatalogService.req(r.paymentMethodId());x.status=BillingConstants.CustomerStatus.ACTIVE;x.createdAt=OffsetDateTime.now(clock);try{return CustomerResponse.from(repo.saveAndFlush(x));}catch(DataIntegrityViolationException e){throw new IllegalStateException("Customer email '"+email+"' is already registered.");}}@Transactional(readOnly=true)public CustomerResponse get(UUID id){return repo.findById(id).map(CustomerResponse::from).orElse(null);}@Transactional(readOnly=true)public List<CustomerResponse> list(){return repo.findAllByOrderByCreatedAtAsc().stream().map(CustomerResponse::from).toList();}}
